package com.bank.diversity;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class DiversityDemo {
    private static final Logger log = Logger.getLogger("Diversity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", "IT", "M"),
            new Employee(2L, "Priya", "Finance", "F"),
            new Employee(3L, "Amit", "IT", "M"),
            new Employee(4L, "Sneha", "Finance", "F"),
            new Employee(5L, "Meena", "IT", "F")
        );
        DiversityService service = new DiversityService();
        Map<String, Map<String, List<Employee>>> report = service.byDeptThenGender(staff);
        report.forEach((dept, byGender) -> byGender.forEach((gender, list) ->
            log.info(() -> dept + "/" + gender + " -> " +
                list.stream().map(Employee::getName).toList())));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    private final String gender;
    Employee(Long id, String name, String department, String gender) {
            this.id = id;
            this.name = name
            this.department = department
            this.gender = gender;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    String getGender() { return gender; }
}

// ─── Would be in service/DiversityService.java ───
class DiversityService {
    // Nested groupingBy: outer by department, inner by gender; TreeMap for stable order.
    Map<String, Map<String, List<Employee>>> byDeptThenGender(List<Employee> employees) {
        return employees.stream()
            .collect(groupingBy(Employee::getDepartment, TreeMap::new,
                        groupingBy(Employee::getGender, TreeMap::new, toList())));
    }
}
